values
-- Constitucional
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-256', 'A Constituicao Federal e a lei suprema do ordenamento juridico brasileiro. Seus principios fundamentais incluem:', '["Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo politico.","Soberania, cidadania e forca militar.","Dignidade, trabalho e propriedade privada absoluta.","Cidadania, pluralismo e monarquia.","Soberania e centralizacao."]'::jsonb, 0, 'O art. 1 da Constituicao lista os principios fundamentais da Republica.', 'easy', 'Principios fundamentais', 'multiple_choice', 'published', 5325, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-257', 'O habeas data e concedido para:', '["Proteger a liberdade de locomocao.","Obter informacoes sobre a propria pessoa em registros publicos.","Anular lei inconstitucional.","Proteger a liberdade de expressao.","Suspender decisao judicial."]'::jsonb, 1, 'O habeas data permite conhecer informacoes relativas a propria pessoa em registros publicos ou de carater publico.', 'medium', 'Remedios constitucionais', 'multiple_choice', 'published', 5326, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-258', 'O mandado de injuncao e cabivel quando:', '["Houver ilegalidade em ato administrativo.","A falta de norma regulamentadora torne inviavel o exercicio de direitos constitucionais.","Houver ameaca a liberdade de locomocao.","A lei for inconstitucional.","Houver erro judiciario."]'::jsonb, 1, 'O mandado de injuncao e cabivel quando a falta de norma regulamentadora inviabiliza o exercicio de direito constitucional.', 'medium', 'Remedios constitucionais', 'multiple_choice', 'published', 5327, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-259', 'A imunidade parlamentar material protege o parlamentar por:', '["Opinioes, palavras e votos no exercicio do mandato.","Atos fora do mandato.","Crimes comuns, sempre.","Acoes civis.","Atos administrativos."]'::jsonb, 0, 'A imunidade material protege opinioes, palavras e votos no exercicio do mandato.', 'medium', 'Imunidades parlamentares', 'multiple_choice', 'published', 5328, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-260', 'A perda da nacionalidade brasileira pode ocorrer por:', '["Casamento com estrangeiro, sempre.","Naturalizacao em pais estrangeiro, conforme a lei, ou cancelamento da naturalizacao.","Mudanca de residencia.","Viagem ao exterior.","Posse de dupla nacionalidade."]'::jsonb, 1, 'A perda da nacionalidade pode ocorrer por naturalizacao em pais estrangeiro ou cancelamento da naturalizacao.', 'medium', 'Nacionalidade', 'multiple_choice', 'published', 5329, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-261', 'A regra da reserva de lei complementar exige lei complementar para:', '["Toda materia.","Materias especificamente previstas na Constituicao, como organizacao judiciaria e tributaria.","Apenas materias penais.","Apenas materias civis.","Apenas materias administrativas."]'::jsonb, 1, 'A reserva de lei complementar exige esse tipo de lei para materias especificamente previstas na Constituicao.', 'medium', 'Processo legislativo', 'multiple_choice', 'published', 5330, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-262', 'O decreto legislativo e utilizado para:', '["Aprovar tratados e acordos internacionais.","Aprovar o orcamento.","Criar cargos.","Autorizar operacoes de credito.","Julgar contas."]'::jsonb, 0, 'O decreto legislativo e utilizado para aprovar tratados e acordos internacionais, entre outros.', 'medium', 'Processo legislativo', 'multiple_choice', 'published', 5331, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-263', 'A medida provisoria tem vigencia de:', '["30 dias, prorrogavel por 30.","60 dias, prorrogavel por 60.","90 dias, prorrogavel por 90.","120 dias, prorrogavel por 60.","15 dias."]'::jsonb, 1, 'A medida provisoria tem vigencia de 60 dias, prorrogavel por 60.', 'medium', 'Medida provisoria', 'multiple_choice', 'published', 5332, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-264', 'O referendo e a consulta popular sobre:', '["Lei ja aprovada, para confirmacao ou rejeicao.","Lei ainda nao aprovada.","Emenda constitucional, sempre.","Tratado internacional.","Decreto."]'::jsonb, 0, 'O referendo e a consulta popular sobre lei ja aprovada, para confirmacao ou rejeicao.', 'medium', 'Referendo e plebiscito', 'multiple_choice', 'published', 5333, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-265', 'O plebiscito e a consulta popular sobre:', '["Lei ja aprovada.","Materia de relevancia, antes da aprovacao da lei.","Tratado internacional.","Decreto.","Sentenca."]'::jsonb, 1, 'O plebiscito e a consulta popular sobre materia de relevancia, antes da aprovacao da lei.', 'medium', 'Referendo e plebiscito', 'multiple_choice', 'published', 5334, 'FCC', 'Tribunais'),
-- Penal
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-266', 'A tipicidade exige que a conduta se enquadre:', '["Na lei penal, de forma material e formal.","Apenas na lei civil.","Apenas na lei administrativa.","Na vontade do juiz.","No costume."]'::jsonb, 0, 'A tipicidade exige que a conduta se enquadre na lei penal, material e formalmente.', 'medium', 'Tipicidade', 'multiple_choice', 'published', 5335, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-267', 'A ilicitude pode ser excluida por:', '["Dolo e culpa.","Excludentes de ilicitude, como legítima defesa, estado de necessidade, estrito cumprimento de dever legal e exercicio regular de direito.","Tentativa.","Reincidencia.","Culpa."]'::jsonb, 1, 'A ilicitude pode ser excluida pelas excludentes de ilicitude.', 'medium', 'Ilicitude', 'multiple_choice', 'published', 5336, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-268', 'A culpabilidade pode ser excluida por:', '["Dolo e culpa.","Inimputabilidade, erro de tipo, erro de proibicao inevitavel, entre outros.","Tipicidade.","Ilicitude.","Reincidencia."]'::jsonb, 1, 'A culpabilidade pode ser excluida por inimputabilidade, erro de tipo, erro de proibicao inevitavel, entre outros.', 'medium', 'Culpabilidade', 'multiple_choice', 'published', 5337, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-269', 'A pena privativa de liberdade pode ser:', '["Apenas reclusao.","Reclusao ou detencao, conforme o crime.","Apenas detencao.","Apenas multa.","Apenas restritiva de direitos."]'::jsonb, 1, 'A pena privativa de liberdade pode ser reclusao ou detencao, conforme o crime.', 'medium', 'Penas', 'multiple_choice', 'published', 5338, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-270', 'A pena de multa, no Codigo Penal:', '["E cumulativa com a prisao, sempre.","Pode ser aplicada isoladamente ou cumulativamente com a privativa de liberdade, conforme o caso.","E proibida.","E substitutiva da prisao, sempre.","E exclusiva de crimes leves."]'::jsonb, 1, 'A multa pode ser aplicada isoladamente ou cumulativamente, conforme o caso.', 'medium', 'Penas', 'multiple_choice', 'published', 5339, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-271', 'As penas restritivas de direitos incluem:', '["Apenas multa.","Prestacao pecuniaria, perda de bens, prestacao de servicos a comunidade, interdicao temporaria de direitos e limitacao de fim de semana.","Apenas prisao.","Apenas advertencia.","Apenas suspensao."]'::jsonb, 1, 'As penas restritivas de direitos incluem prestacao pecuniaria, perda de bens, prestacao de servicos, interdicao e limitacao de fim de semana.', 'medium', 'Penas', 'multiple_choice', 'published', 5340, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-272', 'O regime inicial de cumprimento da pena privativa de liberdade, para crime doloso com pena superior a 8 anos, e:', '["Aberto.","Semiaberto.","Fechado.","Domiciliar.","Livramento condicional."]'::jsonb, 2, 'Para crime doloso com pena superior a 8 anos, o regime inicial e fechado.', 'medium', 'Regime de cumprimento de pena', 'multiple_choice', 'published', 5341, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-273', 'O livramento condicional pode ser concedido quando o condenado:', '["Cumpriu um terco da pena, sem falta grave.","Cumpriu mais de um terco da pena, com bom comportamento, conforme o caso.","Cumpriu toda a pena.","Nao cumpriu nada.","E reincidente."]'::jsonb, 1, 'O livramento condicional exige cumprimento de parte da pena e bom comportamento.', 'medium', 'Livramento condicional', 'multiple_choice', 'published', 5342, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-274', 'A suspensao condicional da pena (sursis) pode ser concedida quando:', '["A pena privativa de liberdade for superior a 4 anos.","A pena privativa de liberdade for igual ou inferior a 2 anos (ou 4, em casos especiais), com requisitos legais.","O crime for hediondo.","O agente for reincidente.","O agente for menor."]'::jsonb, 1, 'O sursis pode ser concedido quando a pena for igual ou inferior a 2 anos (ou 4, em casos especiais).', 'medium', 'Suspensao condicional da pena', 'multiple_choice', 'published', 5343, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-275', 'A progressao de regime pode ser concedida quando o condenado:', '["Nao cumpriu nada.","Cumpriu o requisito temporal e tem bom comportamento carcerario.","E reincidente em crime hediondo.","Cometeu falta grave.","Nao tem residencia."]'::jsonb, 1, 'A progressao exige cumprimento do requisito temporal e bom comportamento carcerario.', 'medium', 'Progressao de regime', 'multiple_choice', 'published', 5344, 'VUNESP', 'Carreiras policiais'),
-- Civil
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-276', 'A capacidade de fato, no Codigo Civil, e plena aos:', '["16 anos.","18 anos.","21 anos.","14 anos.","12 anos."]'::jsonb, 1, 'A capacidade de fato plena e aos 18 anos.', 'easy', 'Capacidade civil', 'multiple_choice', 'published', 5345, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-277', 'O domicilio da pessoa juridica e:', '["O lugar de residencia do representante.","O lugar onde funciona a administracao da pessoa juridica.","O lugar de nascimento do representante.","O lugar de registro.","O lugar de domicilio do socio."]'::jsonb, 1, 'O domicilio da pessoa juridica e o lugar onde funciona a sua administracao.', 'medium', 'Domicilio civil', 'multiple_choice', 'published', 5346, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-278', 'A invalidade do negocio juridico pode ser:', '["Apenas absoluta.","Absoluta ou relativa, conforme o vicio.","Apenas relativa.","Apenas formal.","Apenas material."]'::jsonb, 1, 'A invalidade pode ser absoluta (nulidade) ou relativa (anulabilidade).', 'medium', 'Negocio juridico', 'multiple_choice', 'published', 5347, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-279', 'A nulidade do negocio juridico pode ser declarada:', '["Apenas pelo juiz, a qualquer tempo.","A qualquer tempo, por qualquer interessado.","Apenas pelo Ministerio Publico.","Apenas pelo credor.","Apenas pelo devedor."]'::jsonb, 1, 'A nulidade pode ser declarada a qualquer tempo, por qualquer interessado.', 'medium', 'Negocio juridico', 'multiple_choice', 'published', 5348, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-280', 'A anulabilidade do negocio juridico pode ser invocada:', '["A qualquer tempo.","No prazo legal, pela parte protegida.","Apenas pelo juiz.","Apenas pelo Ministerio Publico.","Apenas pelo credor."]'::jsonb, 1, 'A anulabilidade pode ser invocada no prazo legal pela parte protegida.', 'medium', 'Negocio juridico', 'multiple_choice', 'published', 5349, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-281', 'O pagamento por terceiro, em regra:', '["E sempre invalido.","E valido, se o devedor nao se opuser, com sub-rogacao se for interesse do terceiro.","E proibido.","Exige autorizacao judicial.","Exige aval do credor."]'::jsonb, 1, 'O pagamento por terceiro e valido se o devedor nao se opuser, com sub-rogacao se for interesse do terceiro.', 'medium', 'Pagamento', 'multiple_choice', 'published', 5350, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-282', 'A compensacao, como modo de extincao da obrigacao, exige:', '["Obrigações de mesma especie, liquidas e vencidas, entre as mesmas partes.","Obrigações de especies diferentes.","Obrigações futuras.","Obrigações de terceiros.","Obrigações iliquidas."]'::jsonb, 0, 'A compensacao exige obrigacoes de mesma especie, liquidas e vencidas, entre as mesmas partes.', 'medium', 'Extincao da obrigacao', 'multiple_choice', 'published', 5351, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-283', 'A novacao, como modo de extincao da obrigacao, ocorre quando:', '["Ha substituicao do credor.","Ha substituicao da obrigacao por outra, com extincao da anterior.","Ha pagamento parcial.","Ha compensacao.","Ha confusao."]'::jsonb, 1, 'A novacao ocorre quando ha substituicao da obrigacao por outra, extinguindo a anterior.', 'medium', 'Extincao da obrigacao', 'multiple_choice', 'published', 5352, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-284', 'A confusao, como modo de extincao da obrigacao, ocorre quando:', '["Credor e devedor se tornam a mesma pessoa.","Ha pagamento parcial.","Ha compensacao.","Ha novacao.","Ha prescricao."]'::jsonb, 0, 'A confusao ocorre quando credor e devedor se tornam a mesma pessoa.', 'medium', 'Extincao da obrigacao', 'multiple_choice', 'published', 5353, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-285', 'O enriquecimento sem causa, no Codigo Civil, gera:', '["Apenas responsabilidade penal.","Obrigacao de restituir o enriquecimento, nos termos da lei.","Apenas responsabilidade administrativa.","Apenas responsabilidade trabalhista.","Nenhum efeito."]'::jsonb, 1, 'O enriquecimento sem causa gera obrigacao de restituir o enriquecimento.', 'medium', 'Enriquecimento sem causa', 'multiple_choice', 'published', 5354, 'FCC', 'Tribunais'),
-- Processo Civil
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-286', 'A peticao inicial deve conter, entre outros requisitos:', '["Apenas o pedido.","Os requisitos do art. 319 do CPC, como qualificacao das partes, fato e fundamento, pedido e valor da causa.","Apenas a qualificacao das partes.","Apenas o valor da causa.","Apenas o fundamento."]'::jsonb, 1, 'A peticao inicial deve conter os requisitos do art. 319 do CPC.', 'medium', 'Peticao inicial', 'multiple_choice', 'published', 5355, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-287', 'A contestacao do reu deve ser apresentada no prazo de:', '["5 dias.","15 dias.","30 dias.","5 dias uteis.","10 dias."]'::jsonb, 1, 'A contestacao deve ser apresentada no prazo de 15 dias.', 'medium', 'Contestacao', 'multiple_choice', 'published', 5356, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-288', 'A revelia do reu, no CPC, pode produzir:', '["Presuncao de veracidade dos fatos alegados pelo autor, salvo excecoes.","Condenacao automatica.","Extincao do processo.","Perda do direito material.","Prisao do reu."]'::jsonb, 0, 'A revelia pode produzir presuncao de veracidade dos fatos, salvo excecoes legais.', 'medium', 'Revelia', 'multiple_choice', 'published', 5357, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-289', 'A sentenca de merito resolve:', '["Apenas questoes processuais.","O merito da causa, extinguindo o processo com resolucao do merito.","Apenas a competencia.","Apenas a legitimidade.","Apenas a capacidade."]'::jsonb, 1, 'A sentenca de merito resolve o merito da causa.', 'medium', 'Sentenca', 'multiple_choice', 'published', 5358, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-290', 'O recurso de apelacao e cabivel contra:', '["Sentencas de merito.","Decisoes interlocutorias, em regra.","Despachos.","Atos de secretaria.","Audiencias."]'::jsonb, 0, 'A apelacao e cabivel contra sentencas de merito.', 'medium', 'Recursos', 'multiple_choice', 'published', 5359, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-291', 'O recurso de agravo de instrumento e cabivel contra:', '["Sentencas de merito.","Decisoes interlocutorias que causam gravame irreparavel.","Despachos de mero expediente.","Atos de secretaria.","Audiencias."]'::jsonb, 1, 'O agravo de instrumento e cabivel contra decisoes interlocutorias com gravame irreparavel.', 'medium', 'Recursos', 'multiple_choice', 'published', 5360, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-292', 'O embargos de declaracao servem para:', '["Reformar a sentenca.","Esclarecer obscuridade, eliminar contradicao, suprir omissao ou corrigir erro material.","Ampliar o pedido.","Alterar o merito.","Suspender a execucao."]'::jsonb, 1, 'Os embargos de declaracao servem para esclarecer obscuridade, eliminar contradicao, suprir omissao ou corrigir erro material.', 'medium', 'Recursos', 'multiple_choice', 'published', 5361, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-293', 'A tutela antecipada, no CPC, pode ser concedida quando:', '["Houver apenas pedido do autor.","Houver probabilidade do direito e perigo de dano ou risco ao resultado util do processo.","Houver litigio complexo.","Houver necessidade de pericia.","Houver acordo."]'::jsonb, 1, 'A tutela antecipada pressupoe probabilidade do direito e perigo de dano.', 'medium', 'Tutela provisoria', 'multiple_choice', 'published', 5362, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-294', 'A execucao provisoria pode ocorrer quando:', '["A sentenca for definitiva.","A sentenca for de procedencia e nao houver risco de dano irreparavel, conforme o caso.","A sentenca for de improcedencia.","Houver acordo.","Houver desistencia."]'::jsonb, 1, 'A execucao provisoria pode ocorrer quando a sentenca for de procedencia e nao houver risco de dano irreparavel.', 'medium', 'Execucao', 'multiple_choice', 'published', 5363, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-295', 'O incidente de desconsideracao da personalidade juridica permite:', '["Desconsiderar a personalidade juridica para atingir os socios, nos casos legais.","Extinguir a pessoa juridica.","Suspender o processo.","Transferir o processo.","Anular a sentenca."]'::jsonb, 0, 'O incidente permite desconsiderar a personalidade juridica para atingir os socios, nos casos legais.', 'medium', 'Incidentes processuais', 'multiple_choice', 'published', 5364, 'VUNESP', 'Tribunais'),
-- Processo Penal
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-296', 'O flagrante delito pode ser:', '["Apenas proprio.","Proprio, impróprio ou presumido, conforme o caso.","Apenas impróprio.","Apenas presumido.","Apenas em crimes hediondos."]'::jsonb, 1, 'O flagrante pode ser proprio, impróprio ou presumido.', 'medium', 'Prisao em flagrante', 'multiple_choice', 'published', 5365, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-297', 'A prisao preventiva pode ser decretada para:', '["Garantir a aplicacao da lei penal.","Assegurar a ordem publica, a instrucao criminal ou a aplicacao da lei penal, conforme o caso.","Punir antecipadamente.","Vingar a vitima.","Agradar a opiniao publica."]'::jsonb, 1, 'A prisao preventiva pode ser decretada para assegurar a ordem publica, a instrucao criminal ou a aplicacao da lei penal.', 'medium', 'Prisao preventiva', 'multiple_choice', 'published', 5366, 'FCC', 'Carreiras policiais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-298', 'A prisao domiciliar pode ser concedida quando:', '["O crime for grave.","O preso for maior de 80 anos, gestante, mae de filho com deficiencia, entre outros casos legais.","O preso for reincidente.","O crime for hediondo.","Houver risco de fuga."]'::jsonb, 1, 'A prisao domiciliar pode ser concedida em casos legais, como maior de 80 anos, gestante, mae de filho com deficiencia.', 'medium', 'Prisao domiciliar', 'multiple_choice', 'published', 5367, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-299', 'A busca e apreensao, no processo penal, exige:', '["Apenas autorizacao do delegado.","Mandado judicial, salvo em caso de flagrante ou consentimento, conforme a lei.","Apenas consentimento do morador.","Apenas decisao do promotor.","Apenas decisao do juiz, sem fundamentacao."]'::jsonb, 1, 'A busca e apreensao exige mandado judicial, salvo em caso de flagrante ou consentimento.', 'medium', 'Busca e apreensao', 'multiple_choice', 'published', 5368, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-300', 'A interceptacao telefonica e autorizada quando:', '["Houver suspeita generica.","Houver indicios de autoria e prova da participacao em organizacao criminosa ou crime, com autorizacao judicial.","O delegado solicitar.","O promotor solicitar.","O juiz quiser."]'::jsonb, 1, 'A interceptacao telefonica exige indicios de autoria e prova da participacao em organizacao criminosa ou crime, com autorizacao judicial.', 'medium', 'Interceptacao telefonica', 'multiple_choice', 'published', 5369, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-301', 'A denuncia, no processo penal, e a peça inicial da:', '["Acao civil.","Acao penal publica.","Queixa-crime.","Acao popular.","Acao civil publica."]'::jsonb, 1, 'A denuncia e a peça inicial da acao penal publica.', 'medium', 'Denuncia', 'multiple_choice', 'published', 5370, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-302', 'O tribunal do juri e competente para julgar crimes:', '["Contra a propriedade.","Contra a vida.","Contra a honra.","Contra a administracao publica.","Contra o patrimonio."]'::jsonb, 1, 'O tribunal do juri e competente para julgar crimes contra a vida.', 'medium', 'Tribunal do juri', 'multiple_choice', 'published', 5371, 'FGV', 'OAB'),
